                                    ['word' => 'foregone conclusion', 'ipa' => '/ˌfɔːr.ɡɑːn kənˈkluː.ʒən/', 'meaning_id' => 'hasil yang sudah pasti sebelumnya', 'example' => 'Her promotion was a foregone conclusion.'],
                                    ['word' => 'moot point', 'ipa' => '/ˌmuːt ˈpɔɪnt/', 'meaning_id' => 'hal yang tak perlu diperdebatkan lagi', 'example' => 'Once the funding vanished, the venue was a moot point.'],
