                        [
                            'title' => 'Inference and Implication in Literary Prose',
                            'objective' => 'Read what a sophisticated text implies but never states.',
                            'xp' => 35, 'minutes' => 15,
                            'prerequisites' => ['Idioms and Figurative Language in Context'],
                            'sections' => [
                                ['type' => 'intro', 'title' => 'The unstated center', 'body' => 'In literary and long-form journalism, the most important sentence is often the one that was never written. Writers imply through selection of detail, juxtaposition, and what characters conspicuously do not say. C2 reading means recovering those implications with evidence, not guesswork.'],
                                ['type' => 'explanation', 'title' => 'Four channels of implication', 'body' => "Detail selection — what the camera lingers on: \"He signed the birthday card last, beneath the interns' names\" implies his standing in the office without a word of comment.\n\nJuxtaposition — two facts placed side by side invite a causal or ironic reading: \"The charity's donations doubled. Its director bought a lake house.\"\n\nSignificant silence — a character who answers a different question than the one asked: \"'Did you read my report?' — 'You always format them beautifully.'\"\n\nShift in register — sudden formality can signal distance or anger: a mother calling her son by his full name.\n\nDiscipline: every inference must anchor to a specific textual cue you can point to.", 'body_id' => 'Empat saluran implikasi: pemilihan detail (apa yang disorot penulis), penjajaran dua fakta (mengundang pembacaan kausal/ironis), keheningan yang bermakna (menjawab pertanyaan lain dari yang ditanyakan), dan pergeseran register (formalitas mendadak menandakan jarak/kemarahan). Setiap inferensi harus berpijak pada petunjuk tekstual yang jelas.'],
                                ['type' => 'examples', 'title' => 'Examples', 'meta' => ['items' => [
                                    ['en' => '"She praised the soup, the tablecloth, and the view." (implying the main course failed)', 'id' => 'Memuji sup, taplak, dan pemandangan — menyiratkan hidangan utamanya gagal.'],
                                    ['en' => '"The minister thanked the journalists and took no questions." (implying evasion)', 'id' => 'Berterima kasih kepada wartawan lalu tidak menerima pertanyaan — menyiratkan penghindaran.'],
                                ]]],
                                ['type' => 'vocabulary', 'title' => 'Reading terms', 'meta' => ['words' => [
                                    ['word' => 'juxtaposition', 'ipa' => '/ˌdʒʌk.stə.pəˈzɪʃ.ən/', 'meaning_id' => 'penjajaran (untuk efek makna)', 'example' => 'The juxtaposition of wealth and hunger indicts the city.'],
                                    ['word' => 'conspicuously', 'ipa' => '/kənˈspɪk.ju.əs.li/', 'meaning_id' => 'secara mencolok', 'example' => 'Her name was conspicuously absent from the credits.'],
                                    ['word' => 'evasive', 'ipa' => '/ɪˈveɪ.sɪv/', 'meaning_id' => 'mengelak', 'example' => 'His evasive answer told them everything.'],
                                ]]],
                                ['type' => 'tip', 'title' => 'Tip', 'body' => 'For every inference, complete the sentence: "The text implies X because it says Y." If you cannot fill in Y, you are projecting, not reading.'],
                            ],
                            'exercises' => [[
                                'title' => 'Practice: Inference',
                                'xp' => 18, 'pick' => 0,
                                'questions' => [
                                    ['type' => 'reading', 'prompt' => 'What does the passage imply about the marriage?', 'passage' => 'They had stopped arguing years ago. At dinner she described her day to the dog, who at least tilted his head, and afterward they watched separate screens in the same blue-lit room, courteous as strangers sharing a train compartment.',
                                        'options' => [['The couple has drifted into polite, total estrangement.', true], ['The couple resolved their conflicts and grew closer.', false], ['They argue constantly and loudly.', false]]],
                                    ['type' => 'reading', 'prompt' => 'What is implied by the juxtaposition in the passage?', 'passage' => 'The press release celebrated a record quarter and a bold new chapter of sustainable growth. The same afternoon, facilities staff were told to collect their badges by Friday.',
                                        'options' => [['The celebratory language masks layoffs, and the writer wants the reader to feel the irony.', true], ['The company rewarded facilities staff with new badges.', false], ['The record quarter caused the company to hire more staff.', false]]],
                                    ['type' => 'reading', 'prompt' => '"Did the treatment work?" the reporter asked. The doctor said the trial had been "well designed". What does the doctor\'s reply imply?', 'passage' => '"Did the treatment work?" the reporter asked. The doctor paused, then said the trial had been well designed, rigorously monitored, and conducted at fourteen sites. She praised her colleagues\' dedication at some length.',
                                        'options' => [['By answering a different question, she implies the results were disappointing.', true], ['She directly confirms the treatment worked.', false], ['She implies the trial was badly designed.', false]]],
                                    ['type' => 'multiple_choice', 'prompt' => 'A narrator notes that a CEO\'s "office bookshelf held every management bestseller, spines uncracked". The detail implies the CEO ___.', 'difficulty' => 'hard',
                                        'options' => [['displays books for image rather than reading them', true], ['reads constantly and carefully', false], ['dislikes management theory openly', false]]],
                                    ['type' => 'true_false', 'prompt' => 'A sound inference must be anchored to a specific cue in the text rather than the reader\'s assumptions.', 'config' => ['correct' => true]],
                                    ['type' => 'listening', 'prompt' => 'What does the speaker imply without stating it?', 'audio_text' => 'The new director brings tremendous energy. The office has certainly never been reorganized so many times in a single quarter.',
